  "Quitar línea": "إزالة البند",
  "La suma cuadra con el total.": "المجموع يطابق الإجمالي.",
  "Restan {{amount}} por asignar": "متبقٍ {{amount}} للتوزيع",
  "Te pasaste por {{amount}}": "تجاوزت بمقدار {{amount}}",
  "cuenta externa": "حساب خارجي",
  "Vista de tarjetas": "عرض البطاقات",
